/**
 * Unit tests for org.apache.commons.math.stat.Frequency#addValue(Object)
 */
public class Frequency_addValue_TriageGen2Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }











    @Test(expected = IllegalArgumentException.class)
    public void testAddValue_IncompatibleTypes_ThrowsIllegalArgumentException() {
        // Adding a Long first
        frequency.addValue(10L);
        // Adding a String will cause ClassCastException in TreeMap, 
        // which should be caught and rethrown as IllegalArgumentException
        frequency.addValue("not a long");
    }




}

